34	static void get_date_str(char *buf, size_t size, int days_ago)
35	{
36	    time_t now;
37	    time(&now);
38	    now -= days_ago * 86400;
39	    /* Use gmtime_r + manual UTC+8 offset to avoid NuttX zoneinfo errors */
40	    struct tm tm_val;
41	    time_t local_epoch = now + 8 * 3600;
42	    gmtime_r(&local_epoch, &tm_val);
43	    strftime(buf, size, "%Y-%m-%d", &tm_val);
44	}
45	
46	/* Create directory if not exists (recursive) */
47	static int ensure_dir(const char *path)
48	{
49	    struct stat st = {0};
50	    if (stat(path, &st) == -1) {
51	        /* Try to create parent first */
52	        char parent[256];
53	        strncpy(parent, path, sizeof(parent) - 1);
54	        char *slash = strrchr(parent, '/');
55	        if (slash && slash != parent) {
56	            *slash = '\0';
57	            if (ensure_dir(parent) != OK) return ERROR;
58	        }
59	        
60	        if (mkdir(path, 0755) == -1) {
61	            syslog(LOG_ERR, "[%s] mkdir failed for %s, errno=%d\n", TAG, path, errno);
62	            return ERROR;
63	        }
64	        syslog(LOG_INFO, "[%s] Created directory: %s\n", TAG, path);
65	    }
66	    return OK;
67	}
68	
69	/* Create file with initial content if not exists */
70	static int ensure_file(const char *path, const char *default_content)
71	{
72	    struct stat st = {0};
73	    if (stat(path, &st) == -1) {
74	        /* File does not exist, create it */
75	        FILE *f = fopen(path, "w");
76	        if (!f) {
77	            syslog(LOG_ERR, "[%s] Cannot create %s, errno=%d\n", TAG, path, errno);
78	            return ERROR;
79	        }
80	        if (default_content) {
81	            fputs(default_content, f);
82	        }
83	        fclose(f);
84	        syslog(LOG_INFO, "[%s] Created file: %s\n", TAG, path);
85	    }
86	    return OK;
87	}
