89	int memory_store_init(void)
90	{
91	    syslog(LOG_INFO, "[%s] Initializing memory store at %s\n", TAG, AGENT_DATA_DIR);
92	
93	    /* Create directory structure */
94	    if (ensure_dir(AGENT_DATA_DIR) != OK) return ERROR;
95	    if (ensure_dir(AGENT_CONFIG_DIR) != OK) return ERROR;
96	    if (ensure_dir(AGENT_MEMORY_DIR) != OK) return ERROR;
97	    if (ensure_dir(AGENT_SESSION_DIR) != OK) return ERROR;
98	
99	    /* Create config files with defaults */
100	    const char *default_soul = 
101	        "# Personality\n\n"
102	        "我是 AI Agent，运行在 Vela 嵌入式设备上的 AI 助手。\n\n"
103	        "## 行为准则\n"
104	        "- 简洁高效，回复控制在 200 字以内（除非用户要求详细）\n"
105	        "- 中文优先，用户用英文则用英文回复\n"
106	        "- 只在用户明确要求时才写文件或记笔记，不主动写\n"
107	        "- 善用工具（搜索、时间、文件），但避免不必要的工具调用\n"
108	        "- 诚实说明能力边界，不编造信息\n";
109	
110	    const char *default_user = 
111	        "# User\n\n"
112	        "（首次使用请告诉我你的名字和偏好，我会记住）\n";
113	
114	    const char *default_memory = 
115	        "# Memory\n\n"
116	        "（用户要求记住的信息会保存在这里）\n";
117	
118	    const char *default_heartbeat = 
119	        "# Heartbeat\n\n"
120	        "周期性检查任务（agent 定期执行）：\n"
121	        "- [ ] 示例：检查用户待办事项\n";
122	
123	    const char *default_cron = 
124	        "{\n"
125	        "  \"version\": 1,\n"
126	        "  \"jobs\": []\n"
127	        "}\n";
128	
129	    ensure_file(AGENT_SOUL_FILE, default_soul);
130	    ensure_file(AGENT_USER_FILE, default_user);
131	    ensure_file(AGENT_MEMORY_FILE, default_memory);
132	
133	    char heartbeat_path[128];
134	    snprintf(heartbeat_path, sizeof(heartbeat_path), "%s/HEARTBEAT.md", AGENT_CONFIG_DIR);
135	    ensure_file(heartbeat_path, default_heartbeat);
136	
137	    char cron_path[128];
138	    snprintf(cron_path, sizeof(cron_path), "%s/cron.json", AGENT_CONFIG_DIR);
139	    ensure_file(cron_path, default_cron);
140	
141	    /* Daily notes directory (created on demand by tool_files) */
142	    ensure_dir(AGENT_MEMORY_DIR "/daily");
143	
144	    syslog(LOG_INFO, "[%s] Memory store initialized successfully\n", TAG);
145	    return OK;
146	}
