148	int memory_read_long_term(char *buf, size_t size)
149	{
150	    FILE *f = fopen(AGENT_MEMORY_FILE, "r");
151	    if (!f) {
152	        buf[0] = '\0';
153	        return ERROR;
154	    }
155	    size_t n = fread(buf, 1, size - 1, f);
156	    buf[n] = '\0';
157	    fclose(f);
158	    return OK;
159	}
160	
161	int memory_write_long_term(const char *content)
162	{
163	    FILE *f = fopen(AGENT_MEMORY_FILE, "w");
164	    if (!f) {
165	        syslog(LOG_ERR, "[%s] Cannot write %s\n", TAG, AGENT_MEMORY_FILE);
166	        return ERROR;
167	    }
168	    fputs(content, f);
169	    fclose(f);
170	    syslog(LOG_INFO, "[%s] Long-term memory updated (%d bytes)\n", TAG, (int)strlen(content));
171	    return OK;
172	}
173	
174	int memory_append_today(const char *note)
175	{
176	    char date_str[16];
177	    get_date_str(date_str, sizeof(date_str), 0);
178	
179	    char path[128];
180	    snprintf(path, sizeof(path), "%s/%s.md", AGENT_MEMORY_DIR, date_str);
181	
182	    FILE *f = fopen(path, "a");
183	    if (!f) {
184	        f = fopen(path, "w");
185	        if (!f) {
186	            syslog(LOG_ERR, "[%s] Cannot open %s\n", TAG, path);
187	            return ERROR;
188	        }
189	        fprintf(f, "# %s\n\n", date_str);
190	    }
191	
192	    fprintf(f, "%s\n", note);
193	    fclose(f);
194	    return OK;
195	}
196	
197	int memory_read_recent(char *buf, size_t size, int days)
198	{
199	    size_t offset = 0;
200	    buf[0] = '\0';
201	
202	    for (int i = 0; i < days && offset < size - 1; i++) {
203	        char date_str[16];
204	        get_date_str(date_str, sizeof(date_str), i);
205	
206	        char path[128];
207	        snprintf(path, sizeof(path), "%s/%s.md", AGENT_MEMORY_DIR, date_str);
208	
209	        FILE *f = fopen(path, "r");
210	        if (!f) continue;
211	
212	        if (offset > 0 && offset < size - 4) {
213	            offset += snprintf(buf + offset, size - offset, "\n---\n");
214	        }
215	        size_t n = fread(buf + offset, 1, size - offset - 1, f);
216	        offset += n;
217	        buf[offset] = '\0';
218	        fclose(f);
219	    }
220	    return OK;
221	}
