41	/* Build a comma-separated list of registered tool names.
42	 * Returns number of bytes written (excluding NUL). */
43	
44	static size_t build_tool_names(char *buf, size_t size)
45	{
46	    char *tools_json = tool_registry_get_tools_json();
47	    if (!tools_json) {
48	        return 0;
49	    }
50	
51	    cJSON *arr = cJSON_Parse(tools_json);
52	    free(tools_json);
53	    if (!arr) {
54	        return 0;
55	    }
56	
57	    size_t off = 0;
58	    bool first = true;
59	    cJSON *item;
60	
61	    cJSON_ArrayForEach(item, arr) {
62	        cJSON *name = cJSON_GetObjectItem(item, "name");
63	        if (name && cJSON_IsString(name) && off < size - 1) {
64	            off += snprintf(buf + off, size - off, "%s%s",
65	                first ? "" : ", ", name->valuestring);
66	            first = false;
67	        }
68	    }
69	
70	    cJSON_Delete(arr);
71	    return off;
72	}
