74	static size_t append_file(char *buf, size_t size, size_t offset,
75	                           const char *path, const char *header)
76	{
77	    FILE *f = fopen(path, "r");
78	    if (!f) return offset;
79	
80	    if (header && offset < size - 1) {
81	        offset += snprintf(buf + offset, size - offset, "\n## %s\n\n", header);
82	    }
83	
84	    size_t n = fread(buf + offset, 1, size - offset - 1, f);
85	    offset += n;
86	    buf[offset] = '\0';
87	    fclose(f);
88	    return offset;
89	}
