195	int context_build_messages(const char *history_json, const char *user_message,
196	                                  char *buf, size_t size)
197	{
198	    cJSON *history = cJSON_Parse(history_json);
199	    if (!history) {
200	        history = cJSON_CreateArray();
201	    }
202	
203	    cJSON *user_msg = cJSON_CreateObject();
204	    cJSON_AddStringToObject(user_msg, "role", "user");
205	    cJSON_AddStringToObject(user_msg, "content", user_message);
206	    cJSON_AddItemToArray(history, user_msg);
207	
208	    char *json_str = cJSON_PrintUnformatted(history);
209	    cJSON_Delete(history);
210	
211	    if (json_str) {
212	        strncpy(buf, json_str, size - 1);
213	        buf[size - 1] = '\0';
214	        free(json_str);
215	    } else {
216	        snprintf(buf, size, "[{\"role\":\"user\",\"content\":\"%s\"}]", user_message);
217	    }
218	
219	    return OK;
220	}
