37	static void sanitize_filename(const char *src, char *dst, size_t dst_size)
38	{
39	    size_t i;
40	
41	    for (i = 0; i < dst_size - 1 && src[i] != '\0'; i++) {
42	        unsigned char c = (unsigned char)src[i];
43	        /* Strict allowlist: only alphanumeric, hyphen, underscore, dot */
44	        if ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z')
45	            || (c >= '0' && c <= '9') || c == '-' || c == '_' || c == '.') {
46	            dst[i] = (char)c;
47	        } else {
48	            dst[i] = '_';
49	        }
50	    }
51	    dst[i] = '\0';
52	}
53	
54	static void session_path(const char *chat_id, char *buf, size_t size)
55	{
56	    char safe_id[64];
57	
58	    sanitize_filename(chat_id, safe_id, sizeof(safe_id));
59	    snprintf(buf, size, "%s/tg_%s.jsonl", AGENT_SESSION_DIR, safe_id);
60	}
