68	/**
69	 * Truncate session file to keep only the last max_lines entries.
70	 * Uses a temp file + rename for atomicity.
71	 */
72	static void session_truncate(const char *chat_id, int max_lines)
73	{
74	    char path[128];
75	    session_path(chat_id, path, sizeof(path));
76	
77	    /* Count lines first */
78	    FILE *f = fopen(path, "r");
79	    if (!f) return;
80	
81	    int total_lines = 0;
82	    char line[8192];
83	    while (fgets(line, sizeof(line), f)) {
84	        if (line[0] != '\0' && line[0] != '\n') total_lines++;
85	    }
86	
87	    if (total_lines <= max_lines) {
88	        fclose(f);
89	        return;
90	    }
91	
92	    /* Need to truncate: rewind and skip old lines */
93	    rewind(f);
94	    int skip = total_lines - max_lines;
95	    int skipped = 0;
96	    while (skipped < skip && fgets(line, sizeof(line), f)) {
97	        if (line[0] != '\0' && line[0] != '\n') skipped++;
98	    }
99	
100	    /* Write remaining lines to temp file */
101	    char tmp_path[140];
102	    snprintf(tmp_path, sizeof(tmp_path), "%s.tmp", path);
103	    FILE *tmp = fopen(tmp_path, "w");
104	    if (!tmp) {
105	        fclose(f);
106	        return;
107	    }
108	
109	    while (fgets(line, sizeof(line), f)) {
110	        fputs(line, tmp);
111	    }
112	
113	    fclose(f);
114	    fclose(tmp);
115	
116	    /* Atomic replace */
117	    remove(path);
118	    rename(tmp_path, path);
119	
120	    syslog(LOG_INFO, "[%s] Truncated session %s: %d → %d lines\n",
121	           TAG, chat_id, total_lines, max_lines);
122	}
