124	int session_append(const char *chat_id, const char *role, const char *content)
125	{
126	    pthread_mutex_lock(&s_session_lock);
127	
128	    char path[128];
129	    session_path(chat_id, path, sizeof(path));
130	
131	    FILE *f = fopen(path, "a");
132	    if (!f) {
133	        syslog(LOG_ERR, "[%s] Cannot open session file %s\n", TAG, path);
134	        pthread_mutex_unlock(&s_session_lock);
135	        return ERROR;
136	    }
137	
138	    cJSON *obj = cJSON_CreateObject();
139	    cJSON_AddStringToObject(obj, "role", role);
140	    cJSON_AddStringToObject(obj, "content", content);
141	    cJSON_AddNumberToObject(obj, "ts", (double)time(NULL));
142	
143	    char *line = cJSON_PrintUnformatted(obj);
144	    cJSON_Delete(obj);
145	
146	    if (line) {
147	        fprintf(f, "%s\n", line);
148	        free(line);
149	    }
150	
151	    fclose(f);
152	
153	    /* Auto-truncate: check periodically to avoid overhead on every append.
154	     * Truncate when file exceeds 2x the max to amortize the cost. */
155	    {
156	        static int s_append_count = 0;
157	        if (++s_append_count >= 10) {
158	            s_append_count = 0;
159	            session_truncate(chat_id, AGENT_SESSION_MAX_MSGS * 2);
160	        }
161	    }
162	
163	    pthread_mutex_unlock(&s_session_lock);
164	    return OK;
165	}
