167	int session_get_history_json(const char *chat_id, char *buf, size_t size, int max_msgs)
168	{
169	    pthread_mutex_lock(&s_session_lock);
170	
171	    char path[128];
172	    session_path(chat_id, path, sizeof(path));
173	
174	    FILE *f = fopen(path, "r");
175	    if (!f) {
176	        snprintf(buf, size, "[]");
177	        pthread_mutex_unlock(&s_session_lock);
178	        return OK;
179	    }
180	
181	    /* VLA alternative: static ring buffer (max_msgs is bounded by caller) */
182	    if (max_msgs > AGENT_SESSION_MAX_MSGS) max_msgs = AGENT_SESSION_MAX_MSGS;
183	
184	    cJSON *messages[AGENT_SESSION_MAX_MSGS];
185	    int count = 0;
186	    int write_idx = 0;
187	
188	    char line[8192];
189	    while (fgets(line, sizeof(line), f)) {
190	        size_t len = strlen(line);
191	        if (len > 0 && line[len - 1] == '\n') line[len - 1] = '\0';
192	        if (line[0] == '\0') continue;
193	
194	        cJSON *obj = cJSON_Parse(line);
195	        if (!obj) continue;
196	
197	        if (count >= max_msgs) {
198	            cJSON_Delete(messages[write_idx]);
199	        }
200	        messages[write_idx] = obj;
201	        write_idx = (write_idx + 1) % max_msgs;
202	        if (count < max_msgs) count++;
203	    }
204	    fclose(f);
205	
206	    cJSON *arr = cJSON_CreateArray();
207	    int start = (count < max_msgs) ? 0 : write_idx;
208	    for (int i = 0; i < count; i++) {
209	        int idx = (start + i) % max_msgs;
210	        cJSON *src = messages[idx];
211	
212	        cJSON *entry = cJSON_CreateObject();
213	        cJSON *role    = cJSON_GetObjectItem(src, "role");
214	        cJSON *content = cJSON_GetObjectItem(src, "content");
215	        if (role && content) {
216	            cJSON_AddStringToObject(entry, "role",    role->valuestring);
217	            cJSON_AddStringToObject(entry, "content", content->valuestring);
218	        }
219	        cJSON_AddItemToArray(arr, entry);
220	    }
221	
222	    /* Cleanup ring buffer */
223	    int cleanup_start = (count < max_msgs) ? 0 : write_idx;
224	    for (int i = 0; i < count; i++) {
225	        cJSON_Delete(messages[(cleanup_start + i) % max_msgs]);
226	    }
227	
228	    char *json_str = cJSON_PrintUnformatted(arr);
229	    cJSON_Delete(arr);
230	
231	    if (json_str) {
232	        strncpy(buf, json_str, size - 1);
233	        buf[size - 1] = '\0';
234	        free(json_str);
235	    } else {
236	        snprintf(buf, size, "[]");
237	    }
238	
239	    pthread_mutex_unlock(&s_session_lock);
240	    return OK;
241	}
