266	        if (strstr(entry->d_name, "tg_") && strstr(entry->d_name, ".jsonl")) {
267	            char path[256];
268	            snprintf(path, sizeof(path), "%s/%s", AGENT_SESSION_DIR, entry->d_name);
269	            if (remove(path) == 0) {
270	                count++;
271	            }
272	        }
273	    }
274	    closedir(dir);
275	
276	    syslog(LOG_INFO, "[%s] Cleared all sessions (%d files)\n", TAG, count);
277	    return OK;
278	}
