75	int resp_buf_append(resp_buf_t* rb, const char* data, size_t len)
76	{
77	    while (rb->len + len >= rb->cap) {
78	        size_t new_cap = rb->cap * 2;
79	        if (new_cap > AGENT_LLM_MAX_RESP_SIZE) {
80	            syslog(LOG_ERR, "llm: resp_buf exceeded %d limit\n",
81	                AGENT_LLM_MAX_RESP_SIZE);
82	            return ERROR;
83	        }
84	        char* tmp = realloc(rb->data, new_cap);
85	        if (!tmp)
86	            return ERROR;
87	        rb->data = tmp;
88	        rb->cap = new_cap;
89	    }
90	    memcpy(rb->data + rb->len, data, len);
91	    rb->len += len;
92	    rb->data[rb->len] = '\0';
93	    return OK;
94	}
