139	/* Auto-inject channel/chat_id into cron_add input JSON. */
140	static char* inject_cron_context(const char* tool_name,
141	    const char* input_json, const char* channel, const char* chat_id)
142	{
143	    if (strcmp(tool_name, "cron_add") != 0) {
144	        return NULL;
145	    }
146	    if (!channel || !channel[0] || !chat_id || !chat_id[0]) {
147	        return NULL;
148	    }
149	
150	    cJSON* root = cJSON_Parse(input_json);
151	    if (!root) {
152	        return NULL;
153	    }
154	
155	    cJSON_DeleteItemFromObject(root, "channel");
156	    cJSON_DeleteItemFromObject(root, "chat_id");
157	    cJSON_AddStringToObject(root, "channel", channel);
158	    cJSON_AddStringToObject(root, "chat_id", chat_id);
159	
160	    char* patched = cJSON_PrintUnformatted(root);
161	    cJSON_Delete(root);
162	    return patched;
163	}
