192	 * When call_count > 1, all tools run in parallel threads.
193	 * Uses memory pool for parallel buffers, with heap fallback. */
194	static void add_tool_result_messages(cJSON* messages,
195	    const llm_response_t* resp, char* tool_output,
196	    size_t tool_output_size, const char* msg_channel,
197	    const char* msg_chat_id)
